// Genkit (plugins(genkit = true) in config.nuc): each AI provider of the project config becomes its plugin, only
// for the providers config.nuc enables, and every model of the app gets its schema (flows, structured output).
import 'package:dragonfly/dragonfly.dart';
import 'package:dragonfly_genkit/dragonfly_genkit.dart';
import 'package:genkit_openai/genkit_openai.dart';
import 'package:genkit_assistant/components/assistant/domain/models/summary.dart';

/// Starts Genkit with the AI providers of the connections (startDragonfly calls it).
void startGenkit() {
  final plugins = <GenkitPlugin>[];
  final added = <String>{};
  final models = <String, ModelRef<dynamic>>{};
  final embedders = <String, EmbedderRef<dynamic>>{};
  for (final c in Dragonfly.connections) {
    switch (c) {
      case OpenAI():
        if (added.add('openAI:${c.baseUrl}')) plugins.add(openAI(apiKey: c.apiKey, baseUrl: c.baseUrl));
        models[c.name] = openAI.model(c.model);
        if (c.embedder != null) embedders[c.name] = openAI.embedder(c.embedder!);
      default:
        break;
    }
  }
  DragonflyGenkit.start(plugins: plugins, models: models, embedders: embedders);
  Schemas.register(SchemanticType.from<Summary>(
    jsonSchema: {
      'type': 'object',
      'properties': { 'title': {'type': 'string'}, 'points': {'type': 'array', 'items': {'type': 'string'}} },
      'required': ['title', 'points', ],
    },
    parse: (json) => Summary.fromJson(Map<String, dynamic>.from(json as Map)),
  ));
}
